package com.angle.trading.security;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.context.event.EventListener;import org.springframework.security.authentication.event.AuthenticationSuccessEvent;import org.springframework.stereotype.Component;@Componentpublic class LoginSuccessListener {    private static final Logger log =            LoggerFactory.getLogger(LoginSuccessListener.class);    @EventListener    public void onSuccess(AuthenticationSuccessEvent event) {        log.info("AuthenticationSuccessEvent Triggered");    }}